# 基本条件分支
age = 18
if age >= 18:
    print("成年人")
elif age >= 6:
    print("未成年人")
else:
    print("儿童")

# 多条件
score = 85
if score >= 90:
    grade = "A"
elif score >= 80:
    grade = "B"
elif score >= 70:
    grade = "C"
elif score >= 60:
    grade = "D"
else:
    grade = "F"
print(f"成绩等级：{grade}")

# 基本for循环
for i in range(5):
    print(i, end=" ")  # 0 1 2 3 4

# 遍历列表
fruits = ["苹果", "香蕉", "橙子"]
for fruit in fruits:
    print(fruit)

# 遍历字符串
for char in "Python":
    print(char)

# 遍历字典
d = {"a": 1, "b": 2}
for key in d:
    print(f"{key}: {d[key]}")
